// ===== Function – Decidir estado (Fragmentación de índices) =====
// Entrada: merge de
//  a) Filas del SP usp_MonitoreoFragmentacionIndices
//     Columns esperadas: BaseDeDatos, Esquema, Tabla, NombreIndice, Fragmentacion, Paginas, Estado
//  b) Filas de estado último: base_datos, esquema, tabla, nombre_indice, last_state, last_change_utc
// Salida: 1 item por índice con: state(ALARM|NORMAL), transition(RAISE|HOLD|RECOVER|NONE)

const P = $node["Set - Params"].json || {};
const norm = (s) => String(s ?? "").trim();

const allIn = $input.all().map(it => it.json);
const spRows = [];
const lastRows = [];

for (const r of allIn) {
  const hasSp = ("BaseDeDatos" in r) && ("NombreIndice" in r) && ("Fragmentacion" in r);
  const hasState = ("base_datos" in r) && ("nombre_indice" in r) && ("last_state" in r);
  if (hasSp && !hasState) spRows.push(r);
  else if (hasState && !hasSp) lastRows.push(r);
  else if (hasSp && hasState) spRows.push(r); // si viniera combinado
}

// mapa último estado por clave (db|schema|table|index)
const lastMap = {};
for (const r of lastRows) {
  const k = [r.base_datos, r.esquema, r.tabla, r.nombre_indice].map(norm).join("|");
  lastMap[k] = {
    state: String(r.last_state || "").toUpperCase() || "UNKNOWN",
    last_change_utc: r.last_change_utc || null,
  };
}

const nowIso = new Date().toISOString();
const out = [];
const seen = new Set();

for (const r of spRows) {
  const db  = norm(r.BaseDeDatos);
  const sch = norm(r.Esquema);
  const tab = norm(r.Tabla);
  const idx = norm(r.NombreIndice);
  if (!db || !sch || !tab || !idx) continue;

  const frg = Number(r.Fragmentacion ?? 0);
  const pgs = Number(r.Paginas ?? 0);
  const stNow = String(r.Estado ?? "OK").toUpperCase() === "ALERTA" ? "ALARM" : "NORMAL";

  const k = [db, sch, tab, idx].join("|");
  seen.add(k);
  const prev = lastMap[k]?.state || "UNKNOWN";

  let transition = "NONE";
  if (prev !== "ALARM" && stNow === "ALARM") transition = "RAISE";
  else if (prev === "ALARM" && stNow === "NORMAL") transition = "RECOVER";
  else if (prev === "ALARM" && stNow === "ALARM") transition = "HOLD";

  const alarm_started_at = (transition === "RECOVER") ? (lastMap[k]?.last_change_utc || null) : null;
  const alarm_duration_min =
    (transition === "RECOVER" && alarm_started_at)
      ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000))
      : null;

  out.push({
    json: {
      instance_name: P.instance_name || "N/D",
      base_datos: db,
      esquema: sch,
      tabla: tab,
      nombre_indice: idx,
      fragmentacion_pct: Number.isFinite(frg) ? frg : null,
      paginas: Number.isFinite(pgs) ? pgs : null,
      state: stNow,
      transition,
      alarm_started_at,
      alarm_duration_min,
      ts_utc: nowIso,
      last_change: nowIso,
    },
  });
}

// RECOVERY implícito para índices que desaparecieron estando en ALARM
for (const [k, v] of Object.entries(lastMap)) {
  if (v.state !== "ALARM") continue;
  if (seen.has(k)) continue;
  const [db, sch, tab, idx] = k.split("|");
  const alarm_started_at = v.last_change_utc || null;
  const alarm_duration_min =
    alarm_started_at ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000)) : null;
  out.push({
    json: {
      instance_name: P.instance_name || "N/D",
      base_datos: db, esquema: sch, tabla: tab, nombre_indice: idx,
      fragmentacion_pct: null, paginas: null,
      state: "NORMAL", transition: "RECOVER",
      alarm_started_at, alarm_duration_min,
      ts_utc: nowIso, last_change: nowIso,
    }
  });
}

return out;

function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === ALERTA – Fragmentación índices (MessageCard con encabezado + causas/reco) ===
const P  = $node["Set - Params"].json || {};
const inItems = $items().map(i => i.json);
if (!inItems.length) return [];

const tz = Number(P.tz_offset_hours || 0);
const toLocal = iso => {
  const off = tz * 3600 * 1000;
  return new Date((iso ? new Date(iso).getTime() : Date.now()) + off)
    .toISOString().replace("T"," ").substring(0,19);
};
const num  = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : "0.00");
const trunc = (s, n) => {
  const t = String(s ?? "");
  return t.length <= n ? t : t.slice(0, n - 1) + "…";
};

// Datos base
const inst  = P.instance_name || "N/D";
const when  = toLocal(inItems[0]?.ts_utc);

// Filas en alerta (ya vienen filtradas desde “Decidir estado”, pero reforzamos)
const rows  = inItems
  .filter(r => String(r.state).toUpperCase() === "ALARM" || String(r.state).toUpperCase() === "ALERTA")
  .sort((a,b) => (Number(b.fragmentacion_pct||0) - Number(a.fragmentacion_pct||0)));

const count = rows.length;

// Tabla Markdown
let table  = "| Base de Datos | Esquema | Tabla | Índice | Frag (%) | Páginas | Estado |\n";
table     += "|---------------|---------|-------|--------|----------:|--------:|--------|\n";
for (const r of rows) {
  const bd  = trunc(r.base_datos ?? "N/D", 40);
  const sch = trunc(r.esquema ?? "dbo", 20);
  const tb  = trunc(r.tabla ?? "N/D", 50);
  const ix  = trunc(r.nombre_indice ?? "N/D", 60);
  const fr  = fmt2(r.fragmentacion_pct);
  const pg  = Number(r.paginas || 0);
  const st  = String(r.state || "N/D").toUpperCase();
  table += `| ${bd} | ${sch} | ${tb} | ${ix} | ${fr} | ${pg} | ${st} |\n`;
}

// Encabezado bonito + métricas
const title = `🔴 **ALERTA – Fragmentación de índices • ${inst}**`;
const meta  = `🧩 **Índices en alerta (mostrados):** ${count}\n🕒 **Hora (local):** ${when}`;

// Causas / Recomendaciones (solo si están en Set - Params)
const causes = Array.isArray(P.causes_io) ? P.causes_io : [];
const reco   = Array.isArray(P.reco_io)   ? P.reco_io   : [];

// Limitar tamaño para no inflar el payload
const MAX_TXT = Number(P.msgcard_extras_max_chars || 600);
const causesTxt = causes.length ? ("⚠️ **Causas probables**\n" + trunc(causes.map(x => `• ${x}`).join(" "), MAX_TXT)) : "";
const recoTxt   = reco.length   ? ("🛠️ **Recomendaciones**\n" + trunc(reco.map(x => `• ${x}`).join(" "), MAX_TXT))     : "";

// Ensamble final
const text =
`${title}

${meta}

${table}
${causesTxt ? "\n" + causesTxt : ""}
${recoTxt ? "\n" + recoTxt : ""}`.trim();

const __card = {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    summary: "FRAGMENTACIÓN DETECTADA",
    text
  };
return [{ json: { body: toAdaptiveCardBody(__teamsTextFromCard(__card)) } }];

