  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === RECOVERY – Fragmentación índices (MessageCard con encabezado) ===
const P  = $node["Set - Params"].json || {};
const inItems = $items().map(i => i.json);
if (!inItems.length) return [];

const tz = Number(P.tz_offset_hours || 0);
const toLocal = iso => {
  const off = tz * 3600 * 1000;
  return new Date((iso ? new Date(iso).getTime() : Date.now()) + off)
    .toISOString().replace("T"," ").substring(0,19);
};
const num  = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : "0.00");
const trunc = (s,n) => {
  const t = String(s ?? "");
  return t.length <= n ? t : t.slice(0, n-1) + "…";
};

const inst  = P.instance_name || "N/D";
const when  = toLocal(inItems[0]?.ts_utc);
const limit = Number(P.rows_limit_recovery || 30);

// Filas recuperadas reales (ALARM → OK/NORMAL) presentes en el SP actual
const rec = inItems
  .filter(r => {
    const sr = r.send_recovery === true; // bandera directa del flujo
    const t  = String(r.transition || r.transition_state || "").toUpperCase();
    const st = String(r.state || "").toUpperCase();
    const fr = Number(r.fragmentacion_pct);
    // Acepta send_recovery o transition=RECOVER, y estado OK|NORMAL; evita "ausentes" (fr=0)
    return (sr || t === "RECOVER") && (st === "OK" || st === "NORMAL") && fr > 0;
  })
  .sort((a,b) => (Number(b.fragmentacion_pct||0) - Number(a.fragmentacion_pct||0)))
  .slice(0, limit);

if (!rec.length) {
  return []; // nada que avisar
}

let table  = "| Base de Datos | Esquema | Tabla | Índice | Frag (%) | Páginas | Dur(min) | Estado |\n";
table     += "|---------------|---------|-------|--------|----------:|--------:|---------:|--------|\n";
for (const r of rec) {
  const bd  = trunc(r.base_datos ?? "N/D", 40);
  const sch = trunc(r.esquema ?? "dbo", 20);
  const tb  = trunc(r.tabla ?? "N/D", 50);
  const ix  = trunc(r.nombre_indice ?? "N/D", 60);
  const fr  = fmt2(r.fragmentacion_pct);
  const pg  = Number(r.paginas || 0);
  const dur = Number.isFinite(num(r.alarm_duration_min)) ? String(Math.max(0, Math.round(num(r.alarm_duration_min)))) : "-";
  table += `| ${bd} | ${sch} | ${tb} | ${ix} | ${fr} | ${pg} | ${dur} | OK |\n`;
}

const title = `🟢 **RECOVERY – Fragmentación de índices resuelta • ${inst}**`;
const meta  = `🧩 **Índices recuperados (mostrados):** ${rec.length}\n🕒 **Hora (local):** ${when}`;

const text =
`${title}

${meta}

${table}`.trim();

const __card = {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    summary: "FRAGMENTACIÓN – RECOVERY",
    text
  };
return [{ json: { body: toAdaptiveCardBody(__teamsTextFromCard(__card)) } }];

// === Function – Build registry SQL (fragmentación índices) — sin $node ===

// 1) Entradas (vienen de "Function – Decidir estado")
const rows = $items().map(it => it.json);   // todos los índices (ALARM/OK)
if (!rows.length) return [{ json: { sql: "SELECT 'noop' AS msg;" } }];

// 2) Helper para escapar comillas
const esc = (s) => (s == null ? '' : String(s).replace(/'/g, "''"));

// 3) Tomamos params básicos desde los propios items
const instName = rows[0]?.instance_name || 'N/D';
// Si no quieres fijarlos, puedes dejarlos en blanco y luego actualizarlos en monitoring_instance
const envName  = 'prod';
const regName  = 'onprem';

// 4) Normalizamos filas (formato SP-like)
const all = rows.map(r => ({
  BaseDeDatos: r.base_datos,
  Esquema: r.esquema,
  Tabla: r.tabla,
  NombreIndice: r.nombre_indice,
  Fragmentacion: Number(r.fragmentacion_pct || 0),
  Paginas: Number(r.paginas || 0),
  Estado: (String(r.state).toUpperCase() === 'ALARM' ? 'ALERTA' : 'OK'),
}));

const alerts = all
  .filter(r => r.Estado === 'ALERTA')
  .sort((a, b) => b.Fragmentacion - a.Fragmentacion);

// 5) Componemos el SQL (sin crear tablas: ya las creaste antes)
let sql = `
SET NOCOUNT ON;
SET ARITHABORT ON;
USE OpsObservability;

DECLARE @now_utc DATETIME = SYSUTCDATETIME();
DECLARE @inst_name NVARCHAR(200) = N'${esc(instName)}';
DECLARE @env NVARCHAR(50) = N'${esc(envName)}';
DECLARE @reg NVARCHAR(50) = N'${esc(regName)}';

-- Asegurar instancia
DECLARE @id INT = (SELECT instance_id FROM dbo.monitoring_instance WHERE instance_name=@inst_name);
IF @id IS NULL
BEGIN
  INSERT INTO dbo.monitoring_instance(instance_name, environment, region)
  VALUES(@inst_name, @env, @reg);
  SET @id = SCOPE_IDENTITY();
END;

DECLARE @rid UNIQUEIDENTIFIER = NEWID();
`;

// 6) Inserts detalle
for (const r of all) {
  sql += `
INSERT INTO dbo.monitoring_index_fragmentation
  (ts_utc, instance_id, base_datos, esquema, tabla, nombre_indice,
   fragmentacion_pct, paginas, estado, run_id)
VALUES
  (@now_utc, @id, N'${esc(r.BaseDeDatos)}', N'${esc(r.Esquema)}',
   N'${esc(r.Tabla)}', N'${esc(r.NombreIndice)}',
   ${r.Fragmentacion || 0}, ${r.Paginas || 0},
   N'${esc(r.Estado)}', @rid);
`;
}

// 7) TOPs por ejecución
if (alerts.length === 0) {
  sql += `
INSERT INTO dbo.monitoring_top_entities
  (ts_utc, instance_id, scope_type, scope_key, metric_name, metric_value, rank_n, run_id)
VALUES
  (@now_utc, @id, 'index_frag', 'diag:NO_ALERTS', 'no_data', 0, 0, @rid);
`;
} else {
  let rank = 1;
  for (const r of alerts) {
    const key = `${esc(r.BaseDeDatos)}|${esc(r.Esquema)}|${esc(r.Tabla)}|${esc(r.NombreIndice)}`;
    sql += `
INSERT INTO dbo.monitoring_top_entities
  (ts_utc, instance_id, scope_type, scope_key, metric_name, metric_value, rank_n, run_id)
VALUES
  (@now_utc, @id, 'index_frag', N'${key}', 'fragmentacion_pct', ${r.Fragmentacion}, ${rank}, @rid);
`;
    rank += 1;
  }
}

sql += `
SELECT 'ok' AS message, @now_utc AS ts_utc, @id AS instance_id, @rid AS run_id;
`;

return [{ json: { sql } }];

// === Function – RECOVERY (IO) ===
return $input.all().map(it => {
  const j = it.json;
  const send_recovery = (String(j.state).toUpperCase()==='NORMAL' &&
                         String(j.transition).toUpperCase()==='RECOVER');
  return { json: { ...j, send_recovery } };
});

