DECLARE @base nvarchar(128)   = N'{{$json.base_datos}}';
DECLARE @esq  nvarchar(128)   = N'{{$json.esquema}}';
DECLARE @tab  nvarchar(256)   = N'{{$json.tabla}}';
DECLARE @idx  nvarchar(256)   = N'{{$json.nombre_indice}}';
DECLARE @state varchar(10)    = N'{{$json.state}}';

DECLARE @instance_id int;
SELECT TOP 1 @instance_id = instance_id
FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
WHERE instance_name=@inst;

IF @instance_id IS NULL
BEGIN
  INSERT INTO OpsObservability.dbo.monitoring_instance(instance_name)
  VALUES(@inst);
  SELECT TOP 1 @instance_id = instance_id
  FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
  WHERE instance_name=@inst;
END

IF OBJECT_ID('OpsObservability.dbo.monitoring_index_fragmentation_state','U') IS NULL
BEGIN
  CREATE TABLE OpsObservability.dbo.monitoring_index_fragmentation_state (
    instance_id   INT NOT NULL,
    base_datos    NVARCHAR(200) NOT NULL,
    esquema       NVARCHAR(128) NOT NULL,
    tabla         NVARCHAR(256) NOT NULL,
    nombre_indice NVARCHAR(256) NOT NULL,
    last_state    NVARCHAR(10)  NOT NULL,
    last_change_utc DATETIME     NOT NULL,
    CONSTRAINT PK_mon_idx_frag_state PRIMARY KEY (instance_id, base_datos, esquema, tabla, nombre_indice)
  );
END

MERGE OpsObservability.dbo.monitoring_index_fragmentation_state AS T
USING (SELECT @instance_id AS instance_id, @base AS base_datos, @esq AS esquema, @tab AS tabla, @idx AS nombre_indice) AS S
ON (T.instance_id = S.instance_id AND T.base_datos = S.base_datos AND T.esquema = S.esquema AND T.tabla = S.tabla AND T.nombre_indice = S.nombre_indice)
WHEN MATCHED THEN
  UPDATE SET last_state=@state, last_change_utc=@now_utc
WHEN NOT MATCHED THEN
  INSERT(instance_id, base_datos, esquema, tabla, nombre_indice, last_state, last_change_utc)
  VALUES(@instance_id, @base, @esq, @tab, @idx, @state, @now_utc);
